(7314920, 1141060, 108069, '<td valign="top">This is a piece of art. Those moments when the ordinary is suddenly not at all ordinary make for wonderful presents when you see what''s been captured. And it''s beautifully processed as well.</td>', 'This is a piece of art. Those moments when the ordinary is suddenly not at all ordinary make for wonderful presents when you see what''s been captured. And it''s beautifully processed as well.', '2015-02-08 18:17:11.000000', NULL, 1),
(7314947, 1140994, 108069, '<td valign="top">Love it dark. Great contrast. Rich, fresh, visual pop. Art.</td>', 'Love it dark. Great contrast. Rich, fresh, visual pop. Art.', '2015-02-08 18:37:07.000000', NULL, 1),
(7314969, 1141009, 108069, '<td valign="top">For some reason I''m drawn to the feet, and they perfectly communicate stopped motion. You see birds in flight so often that of course the wings are as they always are, but to see the feet here mid-take-off or landing, it''s time and action frozen. Nicely captured and very nicely processed. Love the grass. Should do very well.</td>', 'For some reason I''m drawn to the feet, and they perfectly communicate stopped motion. You see birds in flight so often that of course the wings are as they always are, but to see the feet here mid-take-off or landing, it''s time and action frozen. Nicely captured and very nicely processed. Love the grass. Should do very well.', '2015-02-08 19:01:23.000000', NULL, 1),
(7314972, 1140790, 108069, '<td valign="top">Beautiful stuff. A little minimalistic tune played quietly in the distance.</td>', 'Beautiful stuff. A little minimalistic tune played quietly in the distance.', '2015-02-08 19:02:46.000000', NULL, 1),
(7315016, 1141009, 114285, '<td valign="top">Seems a little over sharpened, and shame it''s wings are so close to the top of the frame. Nice tones though.<br/> <br/>Already voted.</td>', 'Seems a little over sharpened, and shame it''s wings are so close to the top of the frame. Nice tones though. Already voted.', '2015-02-08 19:44:55.000000', NULL, 1),
(7315017, 1140639, 114285, '<td valign="top">I think you got the white balance wrong on this image bc the milk is quite blue.<br/> <br/>This also suffers from overkill :P)</td>', 'I think you got the white balance wrong on this image bc the milk is quite blue. This also suffers from overkill :P)', '2015-02-08 19:45:21.000000', NULL, 1),
(7315022, 1140790, 114285, '<td valign="top">Love the comp, but shame the birds are so tiny and insignificant, probably a random shot, nevertheless done nicely but not enough to WOW me.</td>', 'Love the comp, but shame the birds are so tiny and insignificant, probably a random shot, nevertheless done nicely but not enough to WOW me.', '2015-02-08 19:47:48.000000', NULL, 1),
