INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7315525, 1140987, 150277, '<td valign="top">I love this.  The motion captured is a bit harder to pull out than in some of the other images since the scene is big, but the detail you captured in that stopped motion is fabulous.  I wonder if the image had been cropped a bit more to emphasize that beautiful whipped batter pattern, if it might have scored even higher.  I too have a hard time understanding what about the shot might have led to scoring the image a 2.  Awesome creativeness!</td>', 'I love this.  The motion captured is a bit harder to pull out than in some of the other images since the scene is big, but the detail you captured in that stopped motion is fabulous.  I wonder if the image had been cropped a bit more to emphasize that beautiful whipped batter pattern, if it might have scored even higher.  I too have a hard time understanding what about the shot might have led to scoring the image a 2.  Awesome creativeness!', '2015-02-09 12:21:40.000000', NULL, 0),
